import numpy as np,pandas as pd,joblib,json
from pathlib import Path
root=Path('/root/nailfold'); idx=pd.read_csv(root/'artifacts/features/dinov2_locked/index.csv'); F=np.load(root/'artifacts/features/dinov2_locked/features.npy').astype('float32'); X=pd.DataFrame(F); X['case']=idx.exam_case_id; C=X.groupby('case').mean().drop(columns=[]); model=joblib.load(root/'artifacts/experiments/microthrombus_binary_candidate_20260916/model.joblib'); roles=pd.read_csv(root/'artifacts/manifest/locked_evaluation_v1_reviewed.csv'); lab=roles[roles.evaluation_role=='locked_test'][['exam_case_id','microthrombus']].set_index('exam_case_id'); z=lab.join(pd.DataFrame({'p':model.predict_proba(C)[:,1],'pred':model.predict(C)},index=C.index),how='inner'); z=z[z.microthrombus.isin(['无','1--2','>2'])]; y=(z.microthrombus!='无').astype(int); from sklearn.metrics import accuracy_score,balanced_accuracy_score,confusion_matrix; print('cases',len(C),'scored',len(z));print('acc',accuracy_score(y,z.pred),'ba',balanced_accuracy_score(y,z.pred),'cm',confusion_matrix(y,z.pred)); print(z.pred.value_counts().to_dict()); (root/'artifacts/experiments/microthrombus_binary_candidate_20260916/locked_eval.json').write_text(json.dumps({'n':len(z),'accuracy':accuracy_score(y,z.pred),'balanced_accuracy':balanced_accuracy_score(y,z.pred),'confusion_matrix':confusion_matrix(y,z.pred).tolist(),'locked_test_used_for_training':False},indent=2))
